from sglang.srt.debug_utils.comparator.unshard.types import AxisInfo

_RECOGNIZED_KEYS = ("sglang_parallel_info", "megatron_parallel_info")

# Maps a ParallelAxis to the (rank_field, size_field) names in the raw info dict.
_AXIS_FIELDS: dict[ParallelAxis, tuple[str, str]] = {
    ParallelAxis.TP: ("tp_rank", "tp_size"),
    ParallelAxis.CP: ("cp_rank", "cp_size"),
}


def normalize_parallel_info(meta: dict) -> dict[ParallelAxis, AxisInfo]:
    """Extract unified parallelism axis information from a rank's metadata dict."""
    present = [key for key in _RECOGNIZED_KEYS if key in meta]

    if len(present) > 1:
        raise ValueError(
            f"Found multiple parallel_info keys in meta: {present}. "
            "Expected at most one."
        )

    if not present:
        return {}

    raw = meta[present[0]]

    result: dict[ParallelAxis, AxisInfo] = {}
    for axis, (rank_field, size_field) in _AXIS_FIELDS.items():
        if rank_field not in raw or size_field not in raw:
            continue
        axis_size = raw[size_field]
        if axis_size == 1:
            continue
        result[axis] = AxisInfo(axis_rank=raw[rank_field], axis_size=axis_size)

    return result
